const removeDuplicates = (arr: string[]): string[] => {
    const uniqueItems: Record<string, boolean> = {};

    const uniqueArray = arr.filter((item) => {
      if (!uniqueItems[item]) {
        uniqueItems[item] = true;
        return true;
      }
      return false;
    });
  
    return uniqueArray;
  };

export const cleanSkills = removeDuplicates(unCleanSkills)

import { useState, useEffect } from 'react';

export const useCachedSkills = () => {
  const [skills, setSkills] = useState([]);

  useEffect(() => {
      const fetchedSkills = cleanSkills
      setSkills(fetchedSkills as []);
  }, [skills]); // Dependency array ensures this effect runs only once

  return skills;
};